pairs=json.load(open(d+'/task-e20f8cb4.json'))

def transform(g):
    h,w=len(g),len(g[0])
    dots=[(i,j) for i in range(h) for j in range(w) if g[i][j]==2]
    out=[row[:] for row in g]
    # find spine pair: same row or same column
    spine=None
    for a in range(len(dots)):
        for b in range(a+1,len(dots)):
            (r1,c1),(r2,c2)=dots[a],dots[b]
            if r1==r2 or c1==c2: spine=((r1,c1),(r2,c2))
    (r1,c1),(r2,c2)=spine
    if r1==r2:
        for j in range(min(c1,c2)+1,max(c1,c2)): out[r1][j]=3
        for (r,c) in dots:
            if (r,c) not in spine:
                for i in range(min(r,r1)+1,max(r,r1)): out[i][c]=3
    else:
        for i in range(min(r1,r2)+1,max(r1,r2)): out[i][c1]=3
        for (r,c) in dots:
            if (r,c) not in spine:
                for j in range(min(c,c1)+1,max(c,c1)): out[r][j]=3
    return out

